import { Hono } from '$C/src/index'
import { validator } from '$C/src/validator'
import { parseBody } from '$C/src/utils/body'

const run = async (name: string, fn: () => Promise<unknown>) => {
  try { console.log(name, '=>', JSON.stringify(await fn())) } catch (e) { console.log(name, 'THREW', String(e)) }
}
const mkForm = () => { const fd = new FormData(); fd.append('foo', 'bar'); return fd }

// native mixed-case
await run('native mixed multipart', async () => {
  const src = new Request('http://x/', { method: 'POST', body: mkForm() })
  const ct = src.headers.get('content-type')!.replace('multipart/form-data', 'Multipart/Form-Data')
  const r = new Request('http://x/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'content-type': ct } })
  return [...(await r.formData()).entries()]
})
await run('native mixed urlencoded', async () => {
  const r = new Request('http://x/', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'Application/X-WWW-Form-Urlencoded' } })
  return [...(await r.formData()).entries()]
})

const app = new Hono()
app.post('/fd-then-parse', async (c) => {
  const fd = await c.req.formData()
  const b = await c.req.parseBody()
  return c.json({ fd: [...fd.entries()], b })
})
app.post('/parse-twice', async (c) => {
  const a = await c.req.parseBody()
  const b = await c.req.parseBody()
  const fd = await c.req.formData()
  return c.json({ a, b, fd: [...fd.entries()], keys: Object.keys(c.req.bodyCache) })
})
app.post('/text-then-parse', async (c) => {
  await c.req.text()
  return c.json(await c.req.parseBody())
})
app.post('/blob-then-parse', async (c) => {
  await c.req.blob()
  return c.json(await c.req.parseBody())
})
app.post('/val', validator('form', (v) => v), async (c) => c.json({ v: c.req.valid('form'), b: await c.req.parseBody() }))
app.onError((e, c) => c.text('ERR ' + String(e), 500))

for (const p of ['/fd-then-parse', '/parse-twice', '/text-then-parse', '/blob-then-parse', '/val']) {
  await run('multipart ' + p, async () => (await app.request(p, { method: 'POST', body: mkForm() })).text())
  await run('urlenc ' + p, async () => (await app.request(p, { method: 'POST', body: new URLSearchParams({ foo: 'bar' }) })).text())
}
// duplicate/comma content-type
await run('comma ct', async () => parseBody(new Request('http://x/', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'application/x-www-form-urlencoded, application/x-www-form-urlencoded' } })))
await run('charset upper', async () => parseBody(new Request('http://x/', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'application/x-www-form-urlencoded;charset=UTF-8' } })))
// Request subclass overriding formData
class MyReq extends Request { async formData() { const f = new FormData(); f.append('custom', '1'); return f } }
await run('subclass formData', async () => parseBody(new MyReq('http://x/', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'application/x-www-form-urlencoded' } })))
// validator edge: uppercase vendor json, Boundary param
const app2 = new Hono()
app2.post('/j', validator('json', (v) => v), (c) => c.json(c.req.valid('json')))
app2.post('/f', validator('form', (v) => v), (c) => c.json(c.req.valid('form')))
app2.onError((e, c) => c.text('ERR ' + String(e), 500))
await run('json space before semi', async () => (await app2.request('/j', { method: 'POST', body: '{"a":1}', headers: { 'content-type': 'Application/JSON ; charset=utf-8' } })).text())
await run('form space before semi', async () => (await app2.request('/f', { method: 'POST', body: 'foo=bar', headers: { 'content-type': 'Application/X-WWW-Form-Urlencoded ; charset=utf-8' } })).text())
EOF
